#ifndef INFINI_OPS_HYGON_RMS_NORM_KERNEL_H_
#define INFINI_OPS_HYGON_RMS_NORM_KERNEL_H_

#include "native/cuda/hygon/caster.cuh"
#include "native/cuda/hygon/runtime_.h"
#include "native/cuda/ops/rms_norm/kernel.h"

namespace infini::ops {

template <>
class Operator<RmsNorm, Device::Type::kHygon>
    : public CudaRmsNorm<Runtime<Device::Type::kHygon>> {
 public:
  using CudaRmsNorm<Runtime<Device::Type::kHygon>>::CudaRmsNorm;
};

}  // namespace infini::ops

#endif

#ifndef INFINI_OPS_CUDA_RMS_NORM_KERNEL_CUH_
#define INFINI_OPS_CUDA_RMS_NORM_KERNEL_CUH_

#include <cstddef>
#include <cstdint>
#include <cub/block/block_reduce.cuh>

#include "native/cuda/caster.cuh"
#include "native/cuda/kernel_commons.cuh"

namespace infini::ops {

namespace {

template <unsigned int block_size, Device::Type kDev, typename TData,
          typename TCompute>
__device__ __forceinline__ TCompute SumSquared(const TData* data_ptr,
                                               size_t count) {
  TCompute ss = 0;
  for (size_t i = threadIdx.x; i < count; i += block_size) {
    TCompute value = Caster<kDev>::template Cast<TCompute>(data_ptr[i]);
    ss += value * value;
  }
  using BlockReduce = cub::BlockReduce<TCompute, block_size>;
  __shared__ typename BlockReduce::TempStorage temp_storage;
  return BlockReduce(temp_storage).Sum(ss);
}

}  // namespace

template <unsigned int block_size, Device::Type kDev, typename TCompute,
          typename TData, typename TWeight>
__global__ void RmsNormKernel(TData* __restrict__ y, int64_t stride_y_batch,
                              int64_t stride_y_nhead,
                              const TData* __restrict__ x,
                              int64_t stride_x_batch, int64_t stride_x_nhead,
                              const TWeight* __restrict__ w, size_t nhead,
                              size_t dim, float epsilon) {
  size_t batch_idx = blockIdx.x / nhead;
  size_t head_idx = blockIdx.x % nhead;

  auto y_ptr = y + batch_idx * stride_y_batch + head_idx * stride_y_nhead;
  auto x_ptr = x + batch_idx * stride_x_batch + head_idx * stride_x_nhead;
  auto w_ptr = w;

  TCompute ss = SumSquared<block_size, kDev, TData, TCompute>(x_ptr, dim);

  __shared__ TCompute rms;
  if (threadIdx.x == 0) {
    rms = Caster<kDev>::template Cast<TCompute>(
        rsqrtf(ss / Caster<kDev>::template Cast<TCompute>(dim) + epsilon));
  }
  __syncthreads();

  for (size_t i = threadIdx.x; i < dim; i += block_size) {
    y_ptr[i] = Caster<kDev>::template Cast<TData>(
        Caster<kDev>::template Cast<TCompute>(x_ptr[i]) *
        Caster<kDev>::template Cast<TCompute>(w_ptr[i]) * rms);
  }
}

}  // namespace infini::ops

#endif

#ifndef INFINI_OPS_CUDA_RMS_NORM_KERNEL_H_
#define INFINI_OPS_CUDA_RMS_NORM_KERNEL_H_

#include <cassert>
#include <cstdint>

#include "base/rms_norm.h"
#include "data_type.h"
#include "dispatcher.h"
#include "native/cuda/kernel_commons.cuh"
#include "native/cuda/ops/rms_norm/kernel.cuh"
#include "native/cuda/runtime_utils.h"

namespace infini::ops {

template <typename Backend>
class CudaRmsNorm : public RmsNorm {
 public:
  using RmsNorm::RmsNorm;

  void operator()(const Tensor input, const Tensor weight, float eps,
                  Tensor out) const override {
    auto cuda_stream =
        static_cast<typename Backend::Stream>(stream_ ? stream_ : 0);

    auto stride_input_batch = input_strides_.size() > 1 ? input_strides_[0] : 0;
    auto stride_input_nhead =
        input_strides_.size() > 1 ? input_strides_[1] : input_strides_[0];
    auto stride_out_batch = out_strides_.size() > 1 ? out_strides_[0] : 0;
    auto stride_out_nhead =
        out_strides_.size() > 1 ? out_strides_[1] : out_strides_[0];

    uint32_t num_blocks = static_cast<uint32_t>(batch_size_ * nhead_);

    assert(out.dtype() == input.dtype());

    int block_size = RuntimeUtils<Backend::kDeviceType>::GetOptimalBlockSize();

    DispatchFunc<ConcatType<List<DataType::kFloat32>, ReducedFloatTypes>,
                 ConcatType<List<DataType::kFloat32>, ReducedFloatTypes>,
                 AllCudaBlockSizes>(
        {static_cast<int64_t>(out.dtype()),
         static_cast<int64_t>(weight.dtype()), block_size},
        [&](auto list_tag) {
          using T = TypeMapType<Backend::kDeviceType, ListGet<0>(list_tag)>;
          using TWeight =
              TypeMapType<Backend::kDeviceType, ListGet<1>(list_tag)>;
          constexpr int kBlockSize = ListGet<2>(list_tag);

          RmsNormKernel<kBlockSize, Backend::kDeviceType, float, T, TWeight>
              <<<num_blocks, kBlockSize, 0, cuda_stream>>>(
                  reinterpret_cast<T*>(out.data()), stride_out_batch,
                  stride_out_nhead, reinterpret_cast<const T*>(input.data()),
                  stride_input_batch, stride_input_nhead,
                  reinterpret_cast<const TWeight*>(weight.data()), nhead_, dim_,
                  eps);
        },
        "CudaRmsNorm::operator()");
  }
};

}  // namespace infini::ops

#endif
